// ---------- 106–118 共用 ----------
// 不依賴 GSAP 的示範游標：沒人操作時沿 8 字形移動，滑鼠移進來就跟著真實游標
function vpointer(l,card,onMove,path){let hover=false;l.addEventListener('pointermove',e=>{const r=l.getBoundingClientRect();hover=true;onMove(e.clientX-r.left,e.clientY-r.top)});l.addEventListener('pointerleave',()=>hover=false);
  ticks.set(card,t=>{if(hover)return;const W=l.offsetWidth,H=l.offsetHeight;if(W)onMove(...(path?path(t,W,H):[W*(.5+.36*Math.sin(t*.9)),H*(.5+.3*Math.sin(t*1.8))]))})}
// 示意風景圖（天空漸層、太陽／月亮、兩層山）
function scene(a,b,m1,m2,sun){const id='sg'+Math.random().toString(36).slice(2);return `<svg viewBox="0 0 160 120" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs><rect width="160" height="120" fill="url(#${id})"/><circle cx="108" cy="42" r="15" fill="${sun}"/><path d="M-30,92 L28,48 L60,72 L96,36 L140,80 L190,56 L190,140 L-30,140Z" fill="${m1}"/><path d="M-30,110 L18,82 L54,102 L92,78 L132,104 L190,84 L190,140 L-30,140Z" fill="${m2}"/></svg>`}
// 示範用箭頭游標
const ARROW='<svg viewBox="0 0 24 24"><path d="M3 2l17 9-7.5 2L9 20z" fill="#fff" stroke="#111" stroke-width="1.6" stroke-linejoin="round"/></svg>';
// ---------- 133 上傳 SVG ----------
// 只保留可描繪的形狀與必要屬性（不保留 script、事件、外部連結、樣式），全部改成描邊
const PLANT='<svg viewBox="0 0 100 100"><path d="M30,62 L70,62"/><path d="M34,62 L38,90 L62,90 L66,62"/><path d="M50,62 C50,48 48,38 50,22"/><path d="M50,46 C40,44 32,36 30,28 C40,28 48,34 50,46"/><path d="M50,38 C58,34 66,26 70,18 C60,18 52,26 50,38"/><path d="M50,28 C46,22 44,16 46,8 C52,14 52,22 50,28"/></svg>';
function cleanSVG(txt){let doc;try{doc=new DOMParser().parseFromString(txt,'image/svg+xml')}catch(e){return null}const src=doc.documentElement;if(!src||src.localName!=='svg'||doc.querySelector('parsererror'))return null;
  const NS='http://www.w3.org/2000/svg',out=document.createElementNS(NS,'svg');let vb=src.getAttribute('viewBox');
  if(!vb||!/^[\d.\s,eE+-]+$/.test(vb)){const w=parseFloat(src.getAttribute('width'))||100,h=parseFloat(src.getAttribute('height'))||100;vb=`0 0 ${w} ${h}`}out.setAttribute('viewBox',vb);
  const SH={path:['d'],line:['x1','y1','x2','y2'],polyline:['points'],polygon:['points'],circle:['cx','cy','r'],ellipse:['cx','cy','rx','ry'],rect:['x','y','width','height','rx','ry']};
  const walk=(node,parent)=>{for(const c of node.children){const n=c.localName;if(n==='g'){const g=document.createElementNS(NS,'g');const tf=c.getAttribute('transform');if(tf&&/^[\w\s(),.+-]+$/.test(tf))g.setAttribute('transform',tf);parent.append(g);walk(c,g)}
    else if(SH[n]){const e=document.createElementNS(NS,n);for(const a of [...SH[n],'transform']){const v=c.getAttribute(a);if(v!=null&&/^[\w\s(),.#%+-]*$/.test(v))e.setAttribute(a,v)}parent.append(e)}}};
  walk(src,out);if(!out.querySelector(Object.keys(SH).join(',')))return null;
  const p=vb.split(/[\s,]+/).map(Number);out.style.strokeWidth=Math.max(p[2]||100,p[3]||100)/110;return out}
// ---------- 141–151 App 用 ----------
function phone(s){const p=el('div','phone');s.append(p);return p}
function mrow(i){const r=el('div','mrow');r.innerHTML='<i></i><span><em></em><em class="s"></em></span>';r.querySelector('i').style.background=GC[i%5];return r}
// ---------- 162–171 hover ----------
// 沒人操作時輪流替元素加上 .hv 模擬 hover（含一次「都沒有」）；滑鼠移進容器就交給真正的 :hover
function autoHover(box,els,card,ms=1300){let k=0,real=false;box.addEventListener('pointerenter',()=>{real=true;els.forEach(e=>e.classList.remove('hv'))});box.addEventListener('pointerleave',()=>real=false);
  card._timers.push(setInterval(()=>{if(real)return;els.forEach((e,i)=>e.classList.toggle('hv',i===k%(els.length+1)));k++},ms))}
// ---------- 172–181 Canvas ----------
// 建立滿版 canvas：處理高解析度、尺寸變化、游標狀態，卡片不在畫面內時暫停運算
function cfx(s,card,setup){const cv=el('canvas','pnet cvx');s.append(cv);const ctx=cv.getContext('2d');const m={x:-1e4,y:-1e4,px:-1e4,py:-1e4,in:false,down:false,click:null};let vis=true;
  const pos=e=>{const r=cv.getBoundingClientRect();m.x=e.clientX-r.left;m.y=e.clientY-r.top};
  cv.addEventListener('pointermove',e=>{pos(e);m.in=true});cv.addEventListener('pointerleave',()=>{m.in=false;m.down=false});
  cv.addEventListener('pointerdown',e=>{pos(e);m.in=true;m.down=true;try{cv.setPointerCapture(e.pointerId)}catch(_){}m.click&&m.click(m.x,m.y)});cv.addEventListener('pointerup',()=>m.down=false);
  const io=new IntersectionObserver(([en])=>vis=en.isIntersecting);io.observe(cv);card._kill.push(()=>io.disconnect());
  let W=0,H=0,st=null,last=0;ticks.set(card,t=>{if(!vis){last=0;return}const dpr=Math.min(2,devicePixelRatio||1),w=s.offsetWidth,h=s.offsetHeight;if(!w)return;
    if(w!==W||h!==H){W=w;H=h;cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);st=setup.init(ctx,W,H,m,cv)}
    const dt=last?Math.min(.05,t-last):.016;last=t;setup.frame(ctx,W,H,t,dt,m,st);m.px=m.x;m.py=m.y});return cv}
const accRGB=s=>{const h=(getComputedStyle(s).getPropertyValue('--a').trim()||'#3dd9b8').replace('#','');return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16))};
const BGD='21,22,26';
// 示範用游標：沒有真實游標時沿 8 字形移動
const demoPt=(t,W,H,m)=>m.in?[m.x,m.y]:[W*(.5+.36*Math.sin(t*.8)),H*(.5+.3*Math.sin(t*1.6))];
// ---------- 202–211 版面 ----------
// 示意用的網頁外框（上方有 Logo 與選單點），回傳內容區
function lyPage(s,menu){const f=el('div','ly-frame');f.innerHTML='<div class="ly-bar"><i class="ly-logo"></i>'+(menu?'':'<span><i></i><i></i><i></i></span>')+'</div>';s.append(f);return f}
// ---------- 232–241 按鈕 ----------
// 建立按鈕（文字包在 span 裡），字級依字數調整
function bxBtn(cls,x){const b=el('button',cls);b.innerHTML='<span></span>';b.querySelector('span').textContent=x;b.setAttribute('aria-label',x);b.style.fontSize=Math.min(5,40/chars(x).length)+'cqw';return b}
// 示範：定時觸發 fn，使用者自己按過後 5 秒內不自動播放
function bxDemo(b,card,fn,ms){let real=0;b.addEventListener('pointerdown',()=>real=Date.now());card._timers.push(setInterval(()=>{if(Date.now()-real>5000)fn()},ms))}
// ---------- 262–271 圖片・媒體 ----------
// 示意圖片：四組風景配色輪流使用，回傳 <div class="md-im"> 的 HTML
const MD_P=[['#9fd3ff','#ffe1b0','#4f7a6a','#264a3f','#fff6d8'],['#ffd9c2','#c9b6ff','#7b6ca8','#3f3566','#fff6e6'],['#1b1f4a','#4a2a6b','#2c2a55','#14122e','#f4f1d0'],['#ffe9a8','#ff9f7a','#c4573f','#6b2a2a','#fffbe8']];
const mdImg=(i,cls='')=>`<div class="md-im ${cls}">${scene(...MD_P[i%MD_P.length])}</div>`;
